from pydantic import BaseModel, Field

try:
    from mcp.server.mcpserver import MCPServer               # mcp >= 2 (nouveau nom)
except ImportError:
    from mcp.server.fastmcp import FastMCP as MCPServer      # mcp 1.x (version du cours)

class Composant(BaseModel):
    reference: str = Field(description="Référence exacte, ex. DHT22")
    quantite: int = Field(ge=0, description="Nombre de pièces")

# llm.with_structured_output(Composant).invoke("J'ai trois DHT22 dans mon tiroir")
# -> Composant(reference='DHT22', quantite=3)

mcp = MCPServer("StockTools")

@mcp.tool()
def quantite_en_stock(reference: str) -> int:
    """Renvoie la quantité en stock d'un composant à partir de sa référence exacte."""
    stock = {"DHT22": 3, "SG90": 2}
    return stock.get(reference.upper(), 0)

if __name__ == "__main__":
    mcp.run(transport="stdio")       # ou "streamable-http"
